sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
	//MSSTRESURY-299/296/298/314 - Preventing Same User performing Maker and Checker Task
    var config = global.JSON.parse(gs.getProperty('x_hsb11_mss_tsd.MSS_Treasury_Fetch_Task_Type'));
    if (config.hasOwnProperty(current.task_type)) {
        var grTask = new GlideRecord('x_hsb11_mss_tsd_treasury_case_task');
        grTask.addEncodedQuery("instruction_case=" + current.instruction_case + "^task_type=" + config[current.task_type]);
        grTask.query();
        while (grTask.next()) {
            if (grTask.assigned_to == current.assigned_to) {
                gs.addErrorMessage("You cannot assign yourself to " + current.task_type + " tasks for this case because you are already assigned to the " + config[current.task_type] + " task.");
                current.setAbortAction(true);
                return;
            }
        }
    }

})(current, previous);
